panels.queryString:
(_sourceCategory = Labs/Fastly OR _sourceCategory = Labs/Fastly) ("\"waf_executed\":\"1\"")
| json "waf_rule_id", "waf_logged", "waf_block", "waf_passed", "waf_anomaly_score", "waf_message", "client_ip", "waf_executed" as waf_rule_id, waf_logged, waf_block, waf_passed, waf_anomaly_score, waf_message, client_ip, waf_executed nodrop
//review logs that went through waf ruleset and
// where URL is logged but not blocked (monitor mode) or where URL is logged and not blocked due to not exceeding threshold settings (block mode)
| where waf_executed="1" and ((waf_logged = "1" and waf_block = "0") or (waf_passed = "1" and waf_anomaly_score > 0))
// table with rule_id, rule message, number of distinct IPs to highlight a broadly firing rule, hit count
| count_distinct(client_ip) as distinct_ips, count as total by waf_rule_id, waf_message
| top 10 waf_rule_id, waf_message, distinct_ips by total

(_sourceCategory = Labs/Fastly OR _sourceCategory = Labs/Fastly) ("\"waf_executed\":\"1\"" "\"waf_block\":\"1\"")
| json "waf_rule_id", "waf_block","waf_message", "client_ip","waf_executed" as waf_rule_id, waf_block, waf_message, client_ip, waf_executed nodrop
//review logs that went through waf ruleset and
| where waf_executed="1" and waf_block="1"
// URLs that are blocked and
// table with rule_id, rule message, number of distinct IPs, hit count
| count_distinct(client_ip) as distinct_ips, count as total by waf_rule_id, waf_message
| top 10 waf_rule_id, waf_message, distinct_ips by total

(_sourceCategory = Labs/Fastly OR _sourceCategory = Labs/Fastly) ("\"waf_executed\":\"1\"")
| json "waf_rule_id", "waf_logged", "waf_block", "waf_passed", "waf_anomaly_score", "waf_message", "waf_executed" as waf_rule_id, waf_logged, waf_block, waf_passed, waf_anomaly_score, waf_message, waf_executed nodrop
//review logs that went through waf ruleset and
// where URL is logged but not blocked (monitor mode) or where URL is logged and not blocked due to not exceeding threshold settings (block mode)
| where  waf_executed="1" and ((waf_logged = "1" and waf_block = "0") or (waf_passed = "1" and waf_anomaly_score > 0))
// graph highlights top WAF messages, it's associated rule_id, and percentage of occurance during reporting window
| count as warns by waf_rule_id, waf_message
| sort by warns
